/** A docs instance's versions as the docs plugin reads them (`versions.json`, `versioned_docs`, `versioned_sidebars`). */
import type { ProjectFiles } from "../project-files.js";
import type { DocsInstance } from "./site.js";

export interface DocsVersion {
  /** `current` or a `versions.json` name. */
  name: string;
  label: string;
  /** Path below the instance's route; `""` for the version served there. */
  path: string;
  /** Project-relative content directory. */
  contentDir: string;
  /** Project-relative sidebars file; `false` without sidebars, undefined for the autogenerated default. */
  sidebarPath: string | false | undefined;
  banner?: "unreleased" | "unmaintained";
  noIndex: boolean;
  /** The version served at the instance's route. */
  last: boolean;
  /** This version's translations, relative to a locale's i18n directory. */
  localized: string;
}

type VersionOptions = { label?: string; path?: string; banner?: string; noIndex?: boolean };

export async function readVersions(project: ProjectFiles, instance: DocsInstance): Promise<DocsVersion[]> {
  const options = instance.options;
  const prefixed = (name: string) => (instance.id === "default" ? name : `${instance.id}_${name}`);
  const file = prefixed("versions.json");
  const released = options.disableVersioning === true || !(await project.exists(file)) ? [] : (JSON.parse(await project.readText(file)) as string[]).map(String);
  const all = options.includeCurrentVersion === false || released.includes("current") ? released : ["current", ...released];
  const only = options.onlyIncludeVersions as string[] | undefined;
  const names = only ? all.filter((name) => only.includes(name)) : all;
  const last = typeof options.lastVersion === "string" ? options.lastVersion : (names.find((name) => name !== "current") ?? "current");
  const configured = (options.versions ?? {}) as Record<string, VersionOptions>;
  const plugin = `docusaurus-plugin-content-docs${instance.id === "default" ? "" : `-${instance.id}`}`;
  return names.map((name) => {
    const own = configured[name] ?? {};
    const current = name === "current";
    // Without a banner option, versions newer than the last are unreleased and older ones unmaintained.
    const banner = own.banner ? (own.banner === "none" ? undefined : own.banner) : name === last ? undefined : names.indexOf(name) < names.indexOf(last) ? "unreleased" : "unmaintained";
    return {
      name,
      label: own.label ?? (current ? "Next" : name),
      path: (own.path ?? (name === last ? "" : current ? "next" : name)).replace(/^\/+|\/+$/g, ""),
      contentDir: current ? instance.path : `${prefixed("versioned_docs")}/version-${name}`,
      sidebarPath: current ? instance.sidebarPath : `${prefixed("versioned_sidebars")}/version-${name}-sidebars.json`,
      ...(banner === "unreleased" || banner === "unmaintained" ? { banner } : {}),
      noIndex: own.noIndex === true,
      last: name === last,
      localized: `${plugin}/${current ? "current" : `version-${name}`}`,
    };
  });
}
